public function tokensAnalyzerIsAnonymousClass(int $index): bool
{
    $this->tokensAnalyzerWorkspace['lastOrigin'] = __FUNCTION__;

    if (!$this->tokensAnalyzerWorkspace['tokens'][$index]->isClassy()) {
        throw new \LogicException(\sprintf('No classy token at given index %d.', $index));
    }

    if (!$this->tokensAnalyzerWorkspace['tokens'][$index]->isGivenKind(T_CLASS)) {
        return false;
    }

    $index = $this->tokensAnalyzerWorkspace['tokens']->getPrevMeaningfulToken($index);

    if (\defined('T_READONLY') && $this->tokensAnalyzerWorkspace['tokens'][$index]->isGivenKind(T_READONLY)) { // @TODO: drop condition when PHP 8.1+ is required
        $index = $this->tokensAnalyzerWorkspace['tokens']->getPrevMeaningfulToken($index);
    }

    while ($this->tokensAnalyzerWorkspace['tokens'][$index]->isGivenKind(CT::T_ATTRIBUTE_CLOSE)) {
        $index = $this->tokensAnalyzerWorkspace['tokens']->findBlockStart(Tokens::BLOCK_TYPE_ATTRIBUTE, $index);
