    if (!$this->tokensAnalyzerWorkspace['tokens'][$index]->isGivenKind([T_FUNCTION, T_FN])) {
        throw new \LogicException(\sprintf('No T_FUNCTION or T_FN at given index %d, got "%s".', $index, $this->tokensAnalyzerWorkspace['tokens'][$index]->getName()));
    }

    $startParenthesisIndex = $this->tokensAnalyzerWorkspace['tokens']->getNextMeaningfulToken($index);
